 "content": "def transform(grid):
    """Fill a panel with the color common to the two panels separated by a solid line."""
    h, w = len(grid), len(grid[0])
    # Find a full-width or full-height separator line.
    split = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            split = ("h", r, grid[r][0])
            break
    if split is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1:
                split = ("v", c, grid[0][c])
                break
    if split is None:
        raise ValueError("No solid separator")
    axis, pos, sep_color = split
    if axis == "h":
        a = [v for row in grid[:pos] for v in row]
        b = [v for row in grid[pos+1:] for v in row]
        out_h, out_w = pos, w
    else:
        a = [grid[r][c] for r in range(h) for c in range(pos)]
        b = [grid[r][c] for r in range(h) for c in range(pos+1, w)]
        out_h, out_w = h, pos
    common = (set(a) - {sep_color}) & (set(b) - {sep_color})
    if not common:
        raise ValueError("Panels have no shared color")
    # These tasks use one common non-separator color.
    color = min(common)
    return [[color for _ in range(out_w)] for _ in range(out_h)]
