 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the solid interior separator and split into equal-sized panels.
    split = None
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and h - r - 1 == r:
            split = ("h", r)
            break
    if split is None:
        for c in range(1, w - 1):
            if len({grid[r][c] for r in range(h)}) == 1 and w - c - 1 == c:
                split = ("v", c)
                break
    if split is None:
        raise ValueError("No centered solid separator between equal panels")
    axis, pos = split
    if axis == "h":
        a, b = grid[:pos], grid[pos + 1:]
    else:
        a = [row[:pos] for row in grid]
        b = [row[pos + 1:] for row in grid]
    shared = (set(x for row in a for x in row) & set(x for row in b for x in row))
    shared.discard(grid[pos][0] if axis == "h" else grid[0][pos])
    if len(shared) != 1:
        raise ValueError(f"Expected one shared panel color, got {shared}")
    background = next(iter(shared))
    return [[3 if a[r][c] == b[r][c] else background
             for c in range(len(a[0]))] for r in range(len(a))]
